using UnityEngine;
using MutationChess.Battle;  namespace MutationChess.Core
{  [CreateAssetMenu(fileName = "EternalFlameBattleStartEffect", menuName = "MutationChess/Relic Effects/Eternal Flame")]  public class EternalFlameBattleStartEffect : CardEffect  {  [Tooltip("")]  public int str = 2;  [Tooltip("")]  public int dex = 2;  [Tooltip("")]  public int block = 10;  [Tooltip("")]  public int energy = 2;  public override void Execute(CombatContext context)  {  var bm = context?.battleManager;  var playerData = context?.targetPlayer ?? bm?.GetPlayerData();  if (playerData == null) return;  playerData.AddBuff(new Buff { type = BuffType.Strength, amount = str, duration = -1 });  playerData.AddBuff(new Buff { type = BuffType.Dexterity, amount = dex, duration = -1 });  if (bm != null)  {  bm.PlayerBlock(block);  }  var handManager = UI.HandManager.Instance;  if (handManager != null)  {  handManager.RestoreEnergy(energy);  }  GameLogger.Log($"[EternalFlame] : +{str} +{dex} ??+{block} +{energy}");  }  public override void Execute(EffectContext context)  {  Execute(context?.combat ?? new CombatContext(context?.battleManager, null, null, null));  }  }
}
